create extension if not exists citext;
create table if not exists users(id bigserial primary key,name varchar(80) not null,email citext unique not null,password_hash text not null,role varchar(20) not null default 'user',verified boolean not null default false,ranking_visible boolean not null default true,created_at timestamptz not null default now());
create table if not exists sessions(id bigserial primary key,user_id bigint not null references users(id) on delete cascade,token_hash text unique not null,expires_at timestamptz not null,created_at timestamptz not null default now());
create table if not exists profiles(id bigserial primary key,user_id bigint not null references users(id) on delete cascade,name varchar(60) not null,kids boolean not null default false,avatar_url text,created_at timestamptz not null default now());
create table if not exists content(id bigserial primary key,type varchar(20) not null,title varchar(180) not null,slug text unique,year int,rating varchar(8),genre varchar(80),description text,cover_url text,banner_url text,status varchar(20) not null default 'draft',metadata jsonb not null default '{}'::jsonb,quality_score int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists seasons(id bigserial primary key,content_id bigint not null references content(id) on delete cascade,number int not null,title varchar(180),unique(content_id,number));
create table if not exists episodes(id bigserial primary key,season_id bigint not null references seasons(id) on delete cascade,number int not null,title varchar(180) not null,duration_seconds int,media_asset_id bigint,intro_start int,intro_end int,unique(season_id,number));
create table if not exists tracks(id bigserial primary key,content_id bigint not null references content(id) on delete cascade,number int not null,title varchar(180) not null,duration_seconds int,media_asset_id bigint,lyrics text,metadata jsonb not null default '{}'::jsonb,unique(content_id,number));
create table if not exists chapters(id bigserial primary key,content_id bigint not null references content(id) on delete cascade,number int not null,title varchar(180) not null,body text,asset_url text,unique(content_id,number));
create table if not exists media_assets(id bigserial primary key,owner_type varchar(30),owner_id bigint,kind varchar(30) not null,source_key text,hls_master_url text,duration_seconds int,status varchar(20) not null default 'uploaded',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());

create table if not exists user_preferences(user_id bigint primary key references users(id) on delete cascade,genres text[] not null default '{}',autoplay boolean not null default true,updated_at timestamptz not null default now());
create table if not exists subscriptions(id bigserial primary key,user_id bigint not null references users(id) on delete cascade,plan varchar(30) not null,status varchar(30) not null default 'inactive',provider varchar(40),provider_customer_id text,provider_subscription_id text,current_period_end timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists subscriptions_one_active_per_user on subscriptions(user_id) where status in ('active','trialing','past_due');
create table if not exists progress(user_id bigint not null references users(id) on delete cascade,content_id bigint not null references content(id) on delete cascade,position_seconds int not null default 0,progress_percent numeric(5,2) not null default 0,updated_at timestamptz not null default now(),primary key(user_id,content_id));
create table if not exists my_list(user_id bigint not null references users(id) on delete cascade,content_id bigint not null references content(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,content_id));
create table if not exists ratings(user_id bigint not null references users(id) on delete cascade,content_id bigint not null references content(id) on delete cascade,rating smallint not null check(rating between 1 and 5),updated_at timestamptz not null default now(),primary key(user_id,content_id));
create table if not exists requests(id bigserial primary key,user_id bigint references users(id) on delete set null,kind varchar(20) not null,media_type varchar(40) not null,title varchar(180) not null,message text,dedupe_key text not null,votes int not null default 1,status varchar(30) not null default 'Novo',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists requests_open_dedupe on requests(dedupe_key) where status not in ('Concluído','Fechado');
create table if not exists notifications(id bigserial primary key,title varchar(160) not null,message text not null,audience jsonb not null default '{}'::jsonb,published_at timestamptz,created_at timestamptz not null default now());
create table if not exists analytics_events(id bigserial primary key,user_id bigint references users(id) on delete set null,event varchar(80) not null,data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists admin_audit_log(id bigserial primary key,admin_user_id bigint references users(id) on delete set null,action varchar(100) not null,entity_type varchar(40),entity_id bigint,data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
